export type KidsBibleEpisode = {
  id: string;
  title: string;
  subtitle: string;
  reference: string;
  book: number;
  chapter: number;
  theme: string;
  story: string[];
  lesson: string;
  ask: string;
  activity: string;
  prayer: string;
};

type EpisodeCopy = Omit<KidsBibleEpisode, "book" | "chapter" | "reference" | "id">;
const episode = (
  id: string,
  book: number,
  chapter: number,
  reference: string,
  copy: EpisodeCopy,
): KidsBibleEpisode => ({ id, book, chapter, reference, ...copy });

/** Child-friendly retellings of major Bible narratives, with passages for reading together. */
export const KIDS_BIBLE_EPISODES: KidsBibleEpisode[] = [
  episode("abram-journey", 1, 12, "Genesis 12:1–9", { title: "Abram Sets Out", subtitle: "A journey begins with trust", theme: "Trust", story: ["God called Abram to leave his home and travel to a place God would show him. Abram set out with Sarai and his family, even though he did not know every detail of the journey.", "God promised to bless Abram and make his family a blessing to others. Abram built an altar along the way to remember God's promise."], lesson: "We can take one good step at a time, even when we do not know everything ahead.", ask: "When have you tried something new without knowing exactly how it would go?", activity: "Draw a path with three steps toward a kind or helpful goal.", prayer: "God, guide me as I take brave and thoughtful steps. Amen." }),
  episode("abraham-stars", 1, 15, "Genesis 15:1–6", { title: "A Sky Full of Stars", subtitle: "Abraham remembers God's promise", theme: "Hope", story: ["Abram wondered how God's promise could come true. God brought him outside at night and invited him to look up at the stars. There were far too many to count.", "The stars helped Abram remember that God had not forgotten the promise. Abram trusted God, even while he was still waiting."], lesson: "Hope can help us keep going while we wait for something important.", ask: "What is something you are hoping for? Who can help you while you wait?", activity: "Make a paper star and write one hope or encouraging word on it.", prayer: "God, stay near while I wait and help me keep hope. Amen." }),
  episode("hagar-seen", 1, 16, "Genesis 16:7–13", { title: "Hagar Is Seen", subtitle: "God meets Hagar in the wilderness", theme: "Being seen", story: ["Hagar was alone in the wilderness and worried about what would happen next. An angel met her beside a spring and spoke to her with care.", "Hagar realized that God had seen her in a hard moment. She gave God a name that means the God who sees me."], lesson: "People who feel unseen or alone matter, and they deserve care and help.", ask: "Who could you check on if they seemed lonely?", activity: "Offer a warm greeting or invite someone to join you today.", prayer: "God, thank You for seeing me. Help me notice people who need care. Amen." }),
  episode("jacob-dream", 1, 28, "Genesis 28:10–17", { title: "Jacob's Dream", subtitle: "A surprising reminder that God is near", theme: "Comfort", story: ["Jacob was traveling alone when night came. He used a stone for a pillow and fell asleep. In a dream, he saw a stairway reaching toward heaven, with angels going up and down.", "God spoke to Jacob and repeated the promise made to his family. When Jacob woke, he said that God had been in that place, even though he had not realized it."], lesson: "We may find comfort in remembering that God is near in unfamiliar places.", ask: "What helps you feel safe when you are somewhere new?", activity: "Draw a place where you feel peaceful and add a sign of hope.", prayer: "God, stay with me at home and wherever I go. Amen." }),
  episode("joseph-forgives", 1, 45, "Genesis 45:1–15", { title: "Joseph Welcomes His Brothers", subtitle: "A family begins to make peace", theme: "Forgiveness", story: ["Joseph's brothers came to Egypt to find food, not knowing who he was. When Joseph finally told them, he cried. His brothers were frightened because of how they had treated him.", "Joseph told them not to be afraid. He forgave them and made a plan for the whole family to live safely in Egypt during the famine."], lesson: "Forgiveness can open a way toward peace, while making room for safety and honest repair.", ask: "What might a person need before they can make peace after being hurt?", activity: "Draw a bridge and write one safe, kind step toward repairing a friendship.", prayer: "God, help us tell the truth, seek safety, and make peace where we can. Amen." }),
  episode("moses-basket", 2, 2, "Exodus 2:1–10", { title: "Moses in a Basket", subtitle: "A baby is kept safe by a caring family", theme: "Courage", story: ["Moses was born at a dangerous time. His mother hid him for as long as she could, then placed him in a carefully made basket among the reeds by the river. His sister watched nearby.", "Pharaoh's daughter found the baby and chose to care for him. Moses' sister helped bring their mother to look after him. Several people acted bravely to protect a child."], lesson: "Caring adults and brave helpers can work together to protect children.", ask: "Who are the safe grown-ups you can go to when you need help?", activity: "Draw a team of helpers who keep children safe.", prayer: "God, thank You for people who care for children. Help us protect one another. Amen." }),
  episode("burning-bush", 2, 3, "Exodus 3:1–12", { title: "The Bush That Was Not Burned Up", subtitle: "Moses hears a call to help", theme: "Helping", story: ["Moses was looking after sheep when he saw a bush that was on fire but did not burn up. As he came closer, God called his name and told him to take off his sandals because the ground was holy.", "God told Moses that the Israelites were suffering and that Moses would help lead them to freedom. Moses felt unsure, but God promised to be with him."], lesson: "When a big job feels frightening, we can ask for help and take the next right step.", ask: "What helps you when a task feels too big?", activity: "Draw a flame-shaped reminder of one person who can encourage you.", prayer: "God, give me courage to help others and wisdom to ask for help. Amen." }),
  episode("passover-meal", 2, 12, "Exodus 12:1–14", { title: "A Meal Before the Journey", subtitle: "Families prepare to leave Egypt", theme: "Remembering", story: ["Moses told the Israelite families to prepare a special meal and be ready to travel. They marked their doorways as God had instructed and ate together, dressed for a journey.", "That night became the beginning of their escape from slavery in Egypt. Later, families remembered the Passover meal and told the story of how God brought them out."], lesson: "Families can remember important stories and the people who helped them.", ask: "What story does your family like to remember together?", activity: "Ask a grown-up to share a family memory over a snack.", prayer: "God, thank You for stories of courage, freedom, and hope. Amen." }),
  episode("red-sea-crossing", 2, 14, "Exodus 14:10–31", { title: "A Way Through the Sea", subtitle: "The Israelites take a brave step toward freedom", theme: "Courage", story: ["The Israelites reached the sea and were frightened when Pharaoh's army came near. Moses told the people not to give up hope and to trust God.", "A strong wind blew through the night, and the sea opened a path. The Israelites crossed to the other side. When they were safe, they sang and thanked God for helping them."], lesson: "When we feel stuck, we can look for wise help and keep moving toward safety.", ask: "Who could help you find a way through a difficult situation?", activity: "Use blue paper to make a sea, then draw a safe path through it.", prayer: "God, guide people who are seeking safety and freedom. Amen." }),
  episode("manna-wilderness", 2, 16, "Exodus 16:11–18", { title: "Food in the Wilderness", subtitle: "The people learn to gather what they need", theme: "Daily care", story: ["In the wilderness, the Israelites worried about having enough food. God told Moses that food would come for the people. In the morning, a small flaky food covered the ground, and the people called it manna.", "Families gathered enough for each day. They learned to trust God's care one day at a time and to share so that everyone had what they needed."], lesson: "We can be grateful for daily needs and remember to share with others.", ask: "What is one everyday thing you are thankful for?", activity: "Make a gratitude list with one food, one person, and one place you are thankful for.", prayer: "God, thank You for daily food and for people who share. Amen." }),
  episode("ten-commandments", 2, 20, "Exodus 20:1–17", { title: "Words for a Caring Community", subtitle: "Moses receives guidance for the people", theme: "Wisdom", story: ["Moses went up Mount Sinai, where God gave him words to guide the people. They taught the Israelites to worship God, respect family, tell the truth, and not take what belonged to others.", "These instructions helped the people live together with care and fairness. They were more than rules to memorize; they showed how a community could treat one another well."], lesson: "Good guidance helps people live with respect, honesty, and care.", ask: "Which rule at home or school helps everyone feel safe?", activity: "Write or draw three ways your family can show respect this week.", prayer: "God, help us choose honesty, respect, and care for one another. Amen." }),
  episode("rahab-helps", 6, 2, "Joshua 2:1–14", { title: "Rahab Helps the Visitors", subtitle: "A brave choice protects people", theme: "Bravery", story: ["Two Israelite visitors came to Jericho. Rahab welcomed them and hid them when the king's messengers came looking for them. She had heard about the God who had helped Israel.", "Rahab asked the visitors to protect her family when the city changed hands. They promised to remember her kindness. Rahab acted bravely and helped keep people safe."], lesson: "Bravery can mean protecting others and asking for safety for the people we love.", ask: "What can you do if someone needs help staying safe?", activity: "Draw a house and fill its windows with words that help people feel safe.", prayer: "God, help us protect people and act with courage and wisdom. Amen." }),
  episode("jordan-crossing", 6, 3, "Joshua 3:7–17", { title: "Crossing the Jordan", subtitle: "A community steps into a new chapter", theme: "Together", story: ["The Israelites reached the Jordan River. The priests carried the ark ahead of the people. When they stepped into the water, the river stopped flowing upstream, and everyone crossed on dry ground.", "The people crossed together into a new place. They remembered that their journey had been full of help, even when the next step seemed uncertain."], lesson: "A community can face change together, one careful step at a time.", ask: "Who is part of your team when you have a big change?", activity: "Make paper footprints and write a helper's name on each one.", prayer: "God, be with us through changes and help us care for one another. Amen." }),
  episode("jericho-walls", 6, 6, "Joshua 6:1–20", { title: "The People of Jericho", subtitle: "The Israelites follow an unusual plan", theme: "Listening", story: ["The city of Jericho had strong walls. God gave Joshua an unusual plan: the people would walk around the city each day, with priests carrying trumpets and the ark.", "On the seventh day, they walked around the city seven times. The priests sounded the trumpets, and the people shouted. The walls fell, and the Israelites entered the city. The story also remembers Rahab, who had protected the visitors."], lesson: "Listening carefully matters, and Bible stories should also remind us to seek peace and protect people.", ask: "When is it important to listen closely to instructions?", activity: "Walk a quiet circle together and notice something new each time around.", prayer: "God, guide us toward peace and help us protect our neighbors. Amen." }),
  episode("deborah-judge", 7, 4, "Judges 4:4–16", { title: "Deborah Leads with Wisdom", subtitle: "A judge encourages Barak", theme: "Leadership", story: ["Deborah was a prophet and judge who helped people settle problems. She called Barak and shared a message that gave him courage to lead Israel's people.", "Barak asked Deborah to go with him, and she agreed. The people worked together, and the land had peace for many years. Deborah's song celebrated the people who had stepped forward to help."], lesson: "Wise leadership can encourage others to work together for what is right.", ask: "Who gives you good advice when you have a hard choice?", activity: "Make a ‘wise words’ card for someone who encourages you.", prayer: "God, help us listen to wise voices and lead with courage and care. Amen." }),
  episode("gideon-courage", 7, 6, "Judges 6:11–16", { title: "Gideon Finds Courage", subtitle: "God calls an unsure person to help", theme: "Courage", story: ["Gideon was hiding when an angel came with a message: God had chosen him to help Israel. Gideon did not feel powerful or important, and he asked how he could possibly do such a thing.", "God promised to be with Gideon. His story reminds us that people who feel small or unsure can still make a difference with help and support."], lesson: "You do not need to feel fearless to take a caring, brave step.", ask: "What is one thing you would like to try with someone's support?", activity: "Draw a shield and write three encouraging words inside it.", prayer: "God, help me find courage and accept help from others. Amen." }),
  episode("ruth-kindness", 8, 1, "Ruth 1:14–18", { title: "Ruth Stays with Naomi", subtitle: "A promise of friendship and care", theme: "Loyalty", story: ["Naomi planned to return to Bethlehem after losing her husband and sons. She told Ruth to go back to her own family, but Ruth chose to stay with Naomi and travel with her.", "Ruth promised to share Naomi's home, people, and faith. The two women began a difficult journey together, caring for one another along the way."], lesson: "Loyal friendship means staying near and offering practical care when someone is hurting.", ask: "How can you show a friend that they are not alone?", activity: "Make a small ‘I'm glad we're friends’ note for someone.", prayer: "God, help us stay kind and faithful to people who need a friend. Amen." }),
  episode("hannah-prays", 9, 1, "1 Samuel 1:9–20", { title: "Hannah's Honest Prayer", subtitle: "Hannah shares what is in her heart", theme: "Prayer", story: ["Hannah was very sad and prayed quietly at the tabernacle. Eli the priest saw her and at first misunderstood what she was doing. Hannah explained that she was pouring out her heart to God.", "Eli listened and blessed her. Later Hannah had a son, Samuel. She kept her promise and brought Samuel to serve at the tabernacle when he was old enough."], lesson: "We can tell God honestly how we feel, and we should listen kindly when someone is hurting.", ask: "What helps you talk about a big feeling?", activity: "Draw a heart and write or dictate one feeling you want to share with a trusted grown-up.", prayer: "God, thank You for listening to every honest prayer. Amen." }),
  episode("samuel-hears", 9, 3, "1 Samuel 3:1–10", { title: "Samuel Hears His Name", subtitle: "A child learns to listen", theme: "Listening", story: ["Samuel was a boy serving with Eli at the tabernacle. One night he heard someone call his name and ran to Eli, thinking Eli needed him. This happened more than once.", "Eli realized God might be calling Samuel. He told Samuel to answer, ‘Speak, for your servant is listening.’ Samuel listened and grew into a trusted prophet."], lesson: "Listening carefully can help us understand what others need and what is right.", ask: "How can you show someone you are really listening?", activity: "Take turns telling a one-minute story while the other person listens without interrupting.", prayer: "God, help me listen with patience and respond with care. Amen." }),
  episode("david-anointed", 9, 16, "1 Samuel 16:1–13", { title: "David Is Chosen", subtitle: "A shepherd boy is anointed king", theme: "Character", story: ["God sent Samuel to Bethlehem to meet Jesse's sons and choose a new king. Samuel first noticed the older brothers, but God told him not to judge only by appearance.", "Jesse brought in his youngest son, David, who had been looking after the sheep. Samuel anointed David, and God's spirit helped him. David's story began before he was famous or powerful."], lesson: "A person's character matters more than how they look or how important they seem.", ask: "What makes someone a good friend or leader?", activity: "Draw a portrait of a person you admire and write their kind qualities around it.", prayer: "God, help me see the good in people and grow a caring heart. Amen." }),
  episode("david-spares-saul", 9, 24, "1 Samuel 24:1–12", { title: "David Chooses Not to Harm Saul", subtitle: "A chance for revenge becomes a chance for restraint", theme: "Self-control", story: ["King Saul was searching for David, and one day Saul entered a cave where David and his friends were hiding. David's friends thought this was his chance to hurt Saul.", "David quietly cut off a piece of Saul's robe, but then he felt troubled and refused to harm the king. Later he spoke honestly to Saul and showed him the piece of cloth as proof."], lesson: "Having the chance to hurt someone does not make it right; self-control can keep people safer.", ask: "What can you do when you feel angry and want to react quickly?", activity: "Practice a pause: take a slow breath, count to five, and find a trusted grown-up.", prayer: "God, help me pause, choose what is right, and seek help when I am upset. Amen." }),
  episode("solomon-wisdom", 11, 3, "1 Kings 3:5–12", { title: "Solomon Asks for Wisdom", subtitle: "A young king asks to lead well", theme: "Wisdom", story: ["God invited King Solomon to ask for what he needed. Solomon asked for a listening heart so he could understand the people and tell right from wrong.", "God was pleased that Solomon asked for wisdom instead of riches or power. Solomon became known for wise decisions, and the story reminds leaders to listen carefully to the people they serve."], lesson: "Wisdom means listening, learning, and choosing what is fair and helpful.", ask: "Who could help you think through a difficult decision?", activity: "Make a ‘wise choice’ checklist: Is it kind? Is it fair? Is it safe?", prayer: "God, give us listening hearts and wisdom to choose what is good. Amen." }),
  episode("elijah-ravens", 11, 17, "1 Kings 17:1–6", { title: "Elijah by the Brook", subtitle: "Food arrives in a lonely place", theme: "Care", story: ["During a time of drought, God told Elijah to hide beside a brook. Elijah drank from the water, and ravens brought him bread and meat morning and evening.", "The brook eventually dried up because there had been no rain. Elijah's journey continued, but for a time he had what he needed in an unexpected place."], lesson: "Help sometimes comes in surprising ways, and people should care for those who are without enough.", ask: "What unexpected help have you received?", activity: "Draw or name three people who help provide food and care in your community.", prayer: "God, thank You for daily care. Help us share with people in need. Amen." }),
  episode("elijah-widow-oil", 11, 17, "1 Kings 17:8–16", { title: "The Widow Shares Her Last Meal", subtitle: "A little flour and oil do not run out", theme: "Sharing", story: ["God sent Elijah to a widow in Zarephath. She was gathering sticks to prepare the last food she had for herself and her son. Elijah asked her to make him a small loaf first.", "The widow chose to share. The jar of flour and jug of oil did not run out during the drought, just as God had promised. The woman, her son, and Elijah had food."], lesson: "Sharing can be difficult when we feel we have little; communities should also make sure everyone has enough.", ask: "What can people share besides food?", activity: "With a grown-up, choose one useful item or kind action to share with someone.", prayer: "God, provide for people who are hungry and help us share generously. Amen." }),
  episode("josiah-book", 12, 22, "2 Kings 22:8–13", { title: "A Book Is Found in the Temple", subtitle: "Josiah listens and chooses to change", theme: "Learning", story: ["While workers were repairing the temple, the high priest found a scroll of God's law. He gave it to the king's secretary, who read it aloud to King Josiah.", "Josiah listened and realized the people had not been following the teachings. He gathered the people so they could hear the words too and began making changes. The story shows a leader willing to learn and act."], lesson: "Learning something important can help us make better choices and repair what is wrong.", ask: "What is something you learned that changed how you act?", activity: "Choose a short Bible passage to read together and share one thing you noticed.", prayer: "God, help us listen, learn, and make good changes. Amen." }),
  episode("esther-speaks", 17, 4, "Esther 4:10–17", { title: "Esther Finds Her Courage", subtitle: "A queen speaks up to protect her people", theme: "Bravery", story: ["Queen Esther learned that her people were in danger. Her cousin Mordecai asked her to speak to the king, but Esther was afraid because approaching the king without being invited was risky.", "Esther asked the Jewish community to fast with her. Then she decided to go to the king and speak. Her courage helped begin a plan to protect her people."], lesson: "Speaking up to protect others can take courage; it is wise to seek support first.", ask: "Who is a trusted person you could talk to if someone were in danger?", activity: "Practice asking a trusted grown-up for help using clear words.", prayer: "God, give courage to people who speak up for those in danger. Amen." }),
  episode("daniel-food", 27, 1, "Daniel 1:8–17", { title: "Daniel Makes a Thoughtful Choice", subtitle: "Friends ask for food that fits their beliefs", theme: "Conviction", story: ["Daniel and his friends were taken to Babylon and offered food from the king's table. Daniel wanted to follow the food practices of his faith, so he respectfully asked the official for a different meal.", "The official agreed to a short test. Daniel and his friends ate vegetables and drank water, and they stayed healthy. They were allowed to continue eating the food they had requested."], lesson: "We can explain our needs respectfully and listen to the people responsible for our care.", ask: "How can you speak politely when something is important to you?", activity: "Practice a respectful request with a grown-up: ‘Could I please… because…?’", prayer: "God, help us be thoughtful, respectful, and true to what is good. Amen." }),
  episode("fiery-furnace", 27, 3, "Daniel 3:16–28", { title: "Three Friends Stand Together", subtitle: "Shadrach, Meshach, and Abednego stay faithful", theme: "Faithfulness", story: ["King Nebuchadnezzar ordered everyone to bow to a golden statue. Shadrach, Meshach, and Abednego refused because they worshipped God. They told the king they would remain faithful, even if he punished them.", "The king ordered them into a blazing furnace, but they were not harmed. The king saw a fourth figure with them and praised their God. Their story shows three friends standing together under pressure."], lesson: "Friends can support one another when they choose what they believe is right.", ask: "How can you support a friend who is being pressured to do something wrong?", activity: "Make a three-friend teamwork drawing and add one way to encourage each other.", prayer: "God, stay near to people in danger and help friends stand together. Amen." }),
  episode("daniel-lions", 27, 6, "Daniel 6:10–23", { title: "Daniel and the Lions", subtitle: "Daniel keeps praying, and God protects him", theme: "Faithfulness", story: ["Some officials were jealous of Daniel and persuaded the king to make a rule against praying to anyone but him. Daniel continued praying to God, as he had always done.", "The king was sad but could not change the rule, so Daniel was placed in a den of lions. In the morning Daniel was safe. The king was amazed that God had protected him."], lesson: "Faith can give people courage, and those in authority should protect people who are treated unfairly.", ask: "What helps you stay hopeful when something feels unfair?", activity: "Write a short prayer or hopeful sentence for someone facing a hard time.", prayer: "God, protect people who are treated unfairly and give them hope. Amen." }),
  episode("jonah-nineveh", 32, 3, "Jonah 3:1–10", { title: "Nineveh Chooses a New Way", subtitle: "A whole city listens and changes", theme: "Fresh starts", story: ["God gave Jonah another chance to go to Nineveh. Jonah went into the city and shared a warning. The people listened, changed their harmful behavior, and showed that they wanted to do better.", "God saw that the people had changed and showed them mercy. Jonah's story asks readers to care about people beyond their own group and to welcome a chance to make things right."], lesson: "People and communities can change direction and make safer, kinder choices.", ask: "What is one small change that could make your home or school kinder?", activity: "Choose a fresh-start action and try it today.", prayer: "God, help us change when we have done wrong and show mercy to others. Amen." }),
  episode("mary-announcement", 40, 1, "Luke 1:26–38", { title: "Mary Hears Surprising News", subtitle: "Mary trusts God with a new beginning", theme: "Trust", story: ["The angel Gabriel visited Mary and told her she would have a son named Jesus. Mary was surprised and asked how this could happen. Gabriel explained that God's spirit would be with her.", "Mary said she would serve God. She trusted God with a future she could not yet see, and her family prepared for a remarkable new beginning."], lesson: "We can ask questions when something surprises us and seek support as we face change.", ask: "What questions do you ask when something new is happening?", activity: "Draw a new beginning you are looking forward to.", prayer: "God, be with families facing change and help us meet it with hope. Amen." }),
  episode("shepherds-good-news", 40, 2, "Luke 2:8–20", { title: "Good News for the Shepherds", subtitle: "The first visitors hear about Jesus", theme: "Joy", story: ["Shepherds were watching their sheep at night when an angel appeared. They were frightened, but the angel said not to be afraid and shared good news: a Savior had been born in Bethlehem.", "A choir of angels praised God. The shepherds hurried to Bethlehem, found Mary, Joseph, and the baby, and then told others what they had seen and heard."], lesson: "Good news can bring joy, and sharing it kindly can encourage others.", ask: "What is some good news you would like to share?", activity: "Make a small card with a kind or joyful message for someone.", prayer: "God, thank You for hope and joy. Help us share good news with kindness. Amen." }),
  episode("magi-visit", 40, 2, "Matthew 2:1–12", { title: "Visitors Follow a Star", subtitle: "The Magi bring gifts to Jesus", theme: "Wonder", story: ["Magi from the east saw a special star and traveled to Jerusalem asking about a newborn king. King Herod was troubled, but the Magi continued their search.", "The star led them to Jesus. They were filled with joy, bowed down, and offered gifts. After a warning in a dream, they went home by another route instead of returning to Herod."], lesson: "Wonder can lead us to seek truth, and wisdom helps us protect people from harm.", ask: "What is something that makes you curious about the world?", activity: "Follow a pretend star around the room to find a small surprise or kind note.", prayer: "God, guide people who seek truth and help us protect one another. Amen." }),
  episode("boy-jesus-temple", 40, 2, "Luke 2:41–52", { title: "Jesus Talks with the Teachers", subtitle: "A young Jesus asks questions and listens", theme: "Learning", story: ["When Jesus was twelve, he traveled with his family to Jerusalem for Passover. On the way home, Mary and Joseph realized he was not with their group. They returned to Jerusalem and searched for him.", "They found Jesus in the temple, listening to the teachers and asking questions. Mary told him how worried they had been. Jesus went home with his parents and continued to grow in wisdom."], lesson: "Curiosity and learning matter, and children need to stay connected with their trusted grown-ups.", ask: "What would you like to learn more about?", activity: "Make a question card and ask a trusted grown-up or teacher to explore it with you.", prayer: "God, help me keep learning and help families care for one another. Amen." }),
  episode("jesus-baptism", 40, 3, "Matthew 3:13–17", { title: "Jesus Is Baptized", subtitle: "A voice of love at the river", theme: "Belonging", story: ["Jesus came to the Jordan River where John was baptizing people. John was surprised and felt unsure, but Jesus asked him to go ahead. John baptized Jesus in the river.", "As Jesus came up from the water, the sky opened, and God's spirit came down like a dove. A voice called Jesus God's beloved Son. The story begins Jesus' public ministry with a reminder of love and belonging."], lesson: "Knowing we are loved can give us courage to do good things.", ask: "Who helps you remember that you are loved?", activity: "Make a paper dove with an encouraging message for someone you care about.", prayer: "God, thank You for loving us. Help us share that love with others. Amen." }),
  episode("calling-disciples", 40, 4, "Matthew 4:18–22", { title: "Jesus Calls the First Disciples", subtitle: "Fishermen become friends and learners", theme: "Community", story: ["Jesus was walking beside the Sea of Galilee when he saw Simon Peter and Andrew fishing. He invited them to follow him and learn to help people. They left their nets and went with him.", "A little farther along, Jesus called James and John, who were working with their father. They joined Jesus too. His group of friends grew as they learned and served together."], lesson: "We learn and do good work better when we support one another.", ask: "Who would you like on your team for a helpful project?", activity: "Draw a team and write one strength each person can share.", prayer: "Jesus, help us learn together and use our gifts to serve. Amen." }),
  episode("water-into-wine", 43, 2, "John 2:1–11", { title: "A Wedding Celebration", subtitle: "Jesus helps when a family has a problem", theme: "Care", story: ["Jesus, his mother, and his disciples were guests at a wedding in Cana. The family ran out of wine, which would have been embarrassing during the celebration. Mary told Jesus about the problem.", "Jesus asked the servants to fill large jars with water. When it was taken to the person in charge, it had become wine. This was the first sign in John's Gospel, and his disciples began to trust him."], lesson: "Noticing a problem early and asking for help can spare someone embarrassment.", ask: "How can you help a host or guest feel comfortable at a celebration?", activity: "Plan a way to help at your next family meal or gathering.", prayer: "God, help us notice needs and care for people gently. Amen." }),
  episode("nicodemus-night", 43, 3, "John 3:1–8", { title: "Nicodemus Visits at Night", subtitle: "A teacher comes with questions", theme: "Curiosity", story: ["Nicodemus was a teacher who came to speak with Jesus at night. He told Jesus that he knew God was with him. Jesus spoke about being born again, using a picture of new life and the wind.", "Nicodemus did not understand everything, but he kept asking questions. Later in John's Gospel, he helps care for Jesus' body. His story shows a person continuing to learn over time."], lesson: "It is okay to ask questions and take time to understand something important.", ask: "What question have you been wondering about lately?", activity: "Start a ‘things I wonder’ notebook with one question in it.", prayer: "God, help us ask honest questions and keep learning with care. Amen." }),
  episode("samaritan-woman", 43, 4, "John 4:4–30", { title: "A Conversation at the Well", subtitle: "Jesus listens to a Samaritan woman", theme: "Respect", story: ["Jesus stopped to rest by a well in Samaria. A woman came to draw water, and Jesus asked her for a drink. In those days, many Jews avoided Samaritans, but Jesus spoke with her respectfully.", "They talked about water, worship, and the woman's life. She was surprised that Jesus listened to her. She went back to town and told people about their conversation."], lesson: "We can treat people with respect even when they are different from us.", ask: "How can you show respect to someone whose life is different from yours?", activity: "Ask someone about a favorite place or tradition and listen without interrupting.", prayer: "God, help us listen and treat every person with dignity. Amen." }),
  episode("paralytic-lowered", 41, 2, "Mark 2:1–12", { title: "Friends Make a Way", subtitle: "A group carries a friend to Jesus", theme: "Friendship", story: ["A crowd filled the house where Jesus was teaching. Four friends carried a man who could not walk, but they could not get through the doorway. They carefully opened a space in the roof and lowered their friend down.", "Jesus saw their faith and told the man his sins were forgiven. Then Jesus told him to get up, pick up his mat, and go home. The man stood up, and the crowd praised God."], lesson: "Good friends find caring ways to include and support one another.", ask: "What could you do to help a friend join an activity?", activity: "Build a safe path with blocks for a small toy and work together to solve the challenge.", prayer: "Jesus, thank You for caring friends. Help us include and support one another. Amen." }),
  episode("jairus-daughter", 41, 5, "Mark 5:21–24, 35–43", { title: "Jesus Visits Jairus's Family", subtitle: "A worried father asks for help", theme: "Comfort", story: ["Jairus, a leader of the synagogue, begged Jesus to come because his young daughter was very ill. On the way, people arrived with sad news that she had died. Jesus told Jairus not to be afraid, but to trust.", "Jesus went into the house with the girl's parents and a few friends. He took the girl's hand and told her to get up. She stood up and walked around, and Jesus asked her family to give her something to eat."], lesson: "When families are worried or grieving, they need comfort, practical care, and trusted helpers.", ask: "What kind words can you offer someone whose family is sick?", activity: "Make a comfort card for someone who is having a difficult day.", prayer: "God, comfort families facing illness and grief, and help us care for them. Amen." }),
  episode("walking-water", 40, 14, "Matthew 14:22–33", { title: "Jesus Comes Across the Water", subtitle: "Peter takes a step of faith", theme: "Courage", story: ["The disciples were in a boat far from shore when wind and waves made rowing difficult. They saw Jesus walking toward them on the water and were frightened, thinking he was a ghost.", "Jesus told them not to be afraid. Peter stepped out of the boat and walked toward Jesus, but became frightened by the wind and began to sink. Jesus reached out and caught him, then climbed into the boat with the disciples."], lesson: "Courage can include asking for help when we feel overwhelmed.", ask: "What helps you ask for help instead of hiding a worry?", activity: "Make a paper boat and write the name of someone you can ask for help.", prayer: "Jesus, reach out to people who are afraid and help us ask for support. Amen." }),
  episode("peter-confesses", 40, 16, "Matthew 16:13–20", { title: "Peter Says Who He Believes Jesus Is", subtitle: "The disciples share what they have learned", theme: "Belief", story: ["Jesus asked his disciples who people said he was. They shared different answers they had heard. Then Jesus asked them who they believed he was.", "Peter answered that Jesus was the Messiah, the Son of the living God. Jesus said Peter was blessed to understand this. The friends were still learning what following Jesus would mean."], lesson: "Beliefs grow through listening, asking questions, and learning together.", ask: "What have you learned about Jesus from someone you trust?", activity: "Draw a speech bubble and write one thing you wonder about Jesus.", prayer: "Jesus, help us learn about You with open and thoughtful hearts. Amen." }),
  episode("transfiguration", 40, 17, "Matthew 17:1–8", { title: "A Bright Moment on the Mountain", subtitle: "The disciples see Jesus in a new way", theme: "Wonder", story: ["Jesus took Peter, James, and John up a high mountain. There, his appearance changed and shone brightly. Moses and Elijah appeared and spoke with him.", "A bright cloud covered them, and a voice said that Jesus was God's beloved Son and that they should listen to him. The disciples were frightened, but Jesus came near and told them not to be afraid."], lesson: "Wonder can be powerful, and a caring presence can help us when we feel afraid.", ask: "What has made you feel wonder or amazement?", activity: "Create a mountain picture with a bright patch of light and a peaceful message.", prayer: "God, help us listen to what is good and comfort people who are afraid. Amen." }),
  episode("martha-mary", 42, 10, "Luke 10:38–42", { title: "Martha and Mary Welcome Jesus", subtitle: "Two sisters show care in different ways", theme: "Balance", story: ["Martha welcomed Jesus into her home and worked hard to prepare everything. Her sister Mary sat near Jesus and listened. Martha became frustrated and asked Jesus to tell Mary to help.", "Jesus answered gently that Martha was worried about many things, while Mary had chosen to listen. The story invites us to make room for both caring work and quiet attention."], lesson: "Good care includes helpful work and making time to listen and rest.", ask: "When do you need a break from doing things so you can listen?", activity: "Plan a few minutes of quiet together after helping with a small task.", prayer: "Jesus, help us serve with joy and make time to listen. Amen." }),
  episode("lost-son", 42, 15, "Luke 15:11–24", { title: "A Father Welcomes His Son Home", subtitle: "A family celebrates a fresh start", theme: "Welcome", story: ["Jesus told about a younger son who asked for his share of the family money and left home. After spending it, he became hungry and decided to return. He planned to ask his father to treat him like a worker.", "While the son was still far away, his father ran to welcome him and hugged him. The father gave him clothes and held a celebration. The older brother was upset, and the story continues by asking how a family can make room for mercy."], lesson: "A fresh start can include welcoming someone back and talking honestly about hurt feelings.", ask: "What might help a family talk through a hard disagreement?", activity: "Draw a welcome-home sign and add one kind way to make peace.", prayer: "God, help us welcome fresh starts and speak honestly about our feelings. Amen." }),
  episode("ten-lepers", 42, 17, "Luke 17:11–19", { title: "One Person Comes Back to Say Thank You", subtitle: "A healed Samaritan remembers gratitude", theme: "Gratitude", story: ["Ten people with a skin disease called out to Jesus for help. Jesus told them to go show themselves to the priests. As they went, they were healed.", "One of them, a Samaritan, came back praising God and thanking Jesus. Jesus noticed that the others had not returned. The story celebrates gratitude and also reminds us to welcome people others might overlook."], lesson: "Noticing help and saying thank you can encourage the people who care for us.", ask: "Who helped you recently, and how could you thank them?", activity: "Make a thank-you note for someone who helped you this week.", prayer: "God, thank You for the people who care for us. Help us remember to say thanks. Amen." }),
  episode("blind-bartimaeus", 41, 10, "Mark 10:46–52", { title: "Jesus Hears Bartimaeus", subtitle: "A blind man calls out and is welcomed", theme: "Being heard", story: ["Bartimaeus was blind and sat beside the road asking for help. When he heard that Jesus was passing, he called out. Some people told him to be quiet, but he called even louder.", "Jesus stopped and asked the crowd to bring Bartimaeus over. Jesus listened to what he wanted, and Bartimaeus was able to see. He followed Jesus along the road."], lesson: "Everyone deserves to be heard, especially people whom others try to silence.", ask: "How can you help make sure a quiet person gets a turn to speak?", activity: "Practice taking turns so everyone in your group gets to share an idea.", prayer: "Jesus, help us listen to people and make room for every voice. Amen." }),
  episode("last-supper", 40, 26, "Matthew 26:17–30", { title: "Jesus Shares a Special Meal", subtitle: "Friends remember Jesus together", theme: "Remembering", story: ["Jesus shared the Passover meal with his disciples. During supper he took bread, gave thanks, broke it, and shared it with them. He also shared a cup and spoke about a new promise.", "Jesus told his friends to remember him. They sang a hymn together before going out. Christians remember this meal in different ways, but it points to Jesus' love and the importance of sharing."], lesson: "Shared meals can help people remember love, belonging, and promises.", ask: "What meal or tradition helps you feel connected to people you love?", activity: "With a grown-up, share a snack and tell one happy memory together.", prayer: "Jesus, thank You for sharing love and hope with Your friends. Amen." }),
  episode("easter-morning", 40, 28, "Matthew 28:1–10", { title: "The First Easter Morning", subtitle: "The women hear that Jesus is risen", theme: "Hope", story: ["Early on the first day of the week, Mary Magdalene and another Mary went to Jesus' tomb. There was an earthquake, and an angel rolled the stone away. The angel told them not to be afraid because Jesus had risen.", "The women hurried away with fear and great joy to tell the disciples. On the way, they met Jesus. The Christian story of Easter begins with their surprising message of hope."], lesson: "Hope can shine even after a time of sadness, and important news can be shared with care.", ask: "What helps you find hope after a hard day?", activity: "Draw a sunrise and add a word that gives you hope.", prayer: "God, thank You for Easter hope. Stay near to everyone who is sad. Amen." }),
  episode("emmaus-road", 42, 24, "Luke 24:13–35", { title: "Friends on the Road to Emmaus", subtitle: "A stranger walks with two sad disciples", theme: "Companionship", story: ["Two of Jesus' followers were walking to Emmaus, talking sadly about what had happened. Jesus came alongside them, but they did not recognize him. He listened as they shared their thoughts.", "As they walked, Jesus explained the Scriptures. When they sat down to eat, he blessed and broke bread, and they recognized him. They hurried back to Jerusalem to tell the others."], lesson: "Walking alongside someone and listening can help them feel less alone.", ask: "How can you be a good listener when a friend is sad?", activity: "Take a short walk together and let each person share one thought.", prayer: "Jesus, walk with people who feel sad and help us listen well. Amen." }),
  episode("thomas-believes", 43, 20, "John 20:24–29", { title: "Thomas Wants to Understand", subtitle: "A friend asks questions after Easter", theme: "Questions", story: ["Thomas was not with the other disciples when the risen Jesus first appeared to them. When they told Thomas, he said he needed to see for himself before he could believe.", "A week later, Jesus came to the disciples again and invited Thomas to see. Thomas answered, ‘My Lord and my God!’ Jesus welcomed Thomas, and his questions became part of the story."], lesson: "Questions can be part of learning, and people deserve patience as they make sense of things.", ask: "What question would you like someone to answer patiently?", activity: "Write a question on a card and find a trusted person to discuss it with.", prayer: "God, welcome our questions and help us learn with patience. Amen." }),
  episode("breakfast-by-sea", 43, 21, "John 21:1–14", { title: "Breakfast by the Sea", subtitle: "Jesus welcomes tired friends with a meal", theme: "Care", story: ["Some disciples went fishing through the night but caught nothing. At dawn, Jesus stood on the shore and told them to cast their net on the other side. They caught so many fish they could barely pull in the net.", "When they reached shore, Jesus had a charcoal fire with bread and fish. He invited them to breakfast. The tired friends were welcomed and cared for."], lesson: "A meal and a warm welcome can comfort people who have had a hard night.", ask: "What simple thing could help someone who is tired?", activity: "Help prepare a simple breakfast or snack with a grown-up.", prayer: "Jesus, thank You for welcoming tired people and caring for our needs. Amen." }),
  episode("pentecost", 44, 2, "Acts 2:1–12", { title: "Many Languages, One Good News", subtitle: "The disciples speak so people can understand", theme: "Understanding", story: ["Jesus' followers were together in Jerusalem when a sound like a strong wind filled the house. They saw what looked like flames above them, and the Holy Spirit helped them speak in other languages.", "Visitors from many places heard the disciples speaking about God's deeds in their own languages. They were amazed that they could understand. The church began sharing its message with people from many nations."], lesson: "People can understand and welcome one another across languages and cultures.", ask: "What language or tradition would you like to learn about?", activity: "Learn how to say ‘hello’ or ‘thank you’ in another language with a grown-up.", prayer: "God, help people from every language and culture understand and care for one another. Amen." }),
  episode("ethiopian-official", 44, 8, "Acts 8:26–40", { title: "Philip Helps a Traveler Understand", subtitle: "A Bible conversation leads to joy", theme: "Learning together", story: ["An angel sent Philip onto a desert road, where he met an Ethiopian official reading the prophet Isaiah. Philip asked if he understood what he was reading. The official invited him to explain.", "Philip told him about Jesus, using the Scripture passage. When they came to water, the official asked to be baptized. Afterward he continued on his way rejoicing."], lesson: "Reading together and asking questions can help people learn; welcome everyone who wants to understand.", ask: "Who could help you understand a Bible passage or a tricky book?", activity: "Read a short passage together and take turns asking what you wonder about.", prayer: "God, thank You for teachers and friends who help us learn. Amen." }),
  episode("paul-conversion", 44, 9, "Acts 9:1–19", { title: "Saul Meets Jesus", subtitle: "A persecutor's life takes a new direction", theme: "Change", story: ["Saul was traveling to Damascus to arrest followers of Jesus. Suddenly a bright light surrounded him, and he heard Jesus ask why Saul was hurting his followers. Saul could not see for three days.", "A disciple named Ananias was afraid to visit Saul, but God told him to go. Ananias welcomed Saul, prayed for him, and Saul's sight returned. Saul was baptized and began a new life sharing the message of Jesus."], lesson: "People can change, but repair also means listening to those who have been hurt and making amends.", ask: "What does a real apology need besides saying ‘I'm sorry’?", activity: "Practice an apology that names the harm and offers a helpful next step.", prayer: "God, help people change harmful ways and make things right. Amen." }),
  episode("peter-cornelius", 44, 10, "Acts 10:9–23, 34–48", { title: "Peter Welcomes Cornelius", subtitle: "A new friendship crosses an old boundary", theme: "Welcome", story: ["Peter had a vision that challenged his ideas about clean and unclean foods. While he was thinking about it, visitors arrived from Cornelius, a Roman officer who wanted to learn about God.", "Peter went to Cornelius's home and realized God welcomed people from every nation. As Peter spoke, the Holy Spirit came upon the listeners. Peter welcomed them and baptized them."], lesson: "God's welcome is wider than our old assumptions, and we can learn from people across boundaries.", ask: "How can you welcome someone who is new to your group?", activity: "Plan a friendly greeting for someone who has recently joined your class or community.", prayer: "God, help us welcome people from every nation and background. Amen." }),
  episode("paul-silas-song", 44, 16, "Acts 16:22–34", { title: "Paul and Silas Sing in Jail", subtitle: "A midnight earthquake opens the doors", theme: "Hope", story: ["Paul and Silas were beaten and put in jail after helping a young woman. Their feet were fastened in stocks. At midnight, they prayed and sang hymns while the other prisoners listened.", "A strong earthquake shook the jail, and the doors opened. The jailer thought the prisoners had escaped, but Paul called out that they were all still there. The jailer asked how to be saved, and he and his household heard about Jesus."], lesson: "Hope can help people endure hardship, and people in custody deserve safety and humane treatment.", ask: "What song, prayer, or kind words help you through a difficult time?", activity: "Share a hopeful song or encouraging words with someone who needs them.", prayer: "God, protect people in difficult places and give them hope and help. Amen." }),
  episode("paul-shipwreck", 44, 27, "Acts 27:18–26, 39–44", { title: "A Storm at Sea", subtitle: "Paul encourages everyone on the ship", theme: "Encouragement", story: ["Paul was traveling by ship when a fierce storm lasted for many days. The sailors threw cargo overboard, and the passengers were afraid they would not survive. Paul encouraged everyone to eat and not lose hope.", "The ship ran aground near an island, but everyone made it safely to shore. The story remembers the people who worked together and the encouragement Paul gave during danger."], lesson: "In a crisis, calm words, teamwork, and practical help can protect people.", ask: "What could you do to help someone stay calm in an emergency?", activity: "With a grown-up, learn the names of safe adults and the local emergency number.", prayer: "God, protect people in storms and help rescuers work safely. Amen." }),
  episode("new-jerusalem", 66, 21, "Revelation 21:1–5", { title: "A Picture of a Hopeful World", subtitle: "The Bible ends with healing and peace", theme: "Hope", story: ["John's vision in Revelation shows a new heaven and a new earth. God lives with the people, and death, mourning, crying, and pain are no more. The one seated on the throne says, ‘I am making everything new.’", "The picture is a promise of healing and peace. It helps people who are suffering imagine a world where everyone is safe and cared for."], lesson: "Hope for healing can inspire us to make our homes and communities more peaceful now.", ask: "What would a world with no hurt or tears be like?", activity: "Draw a hopeful world and add one caring action you can do today.", prayer: "God, bring healing to the world and help us share hope. Amen." }),
];
